cd /home/sandbox/workspace && cat > src/App.tsx <<'EOF'
import {
    BlockType,
    PageConstructor,
    PageConstructorProvider,
    PageContent,
    Theme,
} from '@gravity-ui/page-constructor';
import '@gravity-ui/page-constructor/styles/styles.scss';

import './App.css';

const SIGNUP_URL = '/signup';

const content: PageContent = {
    animated: false,
    blocks: [
        {
            type: BlockType.HeaderBlock,
            overtitle: 'Учёт времени для команд',
            title: 'Знайте, куда уходит рабочее время команды',
            description:
                'Простой трекер, который показывает загрузку людей и проектов без таблиц и ручных отчётов.',
            width: 'm',
            centered: true,
        },
        {
            type: BlockType.ExtendedFeaturesBlock,
            title: {text: 'Почему команды выбирают нас'},
            items: [
                {
                    title: 'Старт за минуту',
                    text: 'Пригласите коллег по ссылке и запускайте таймер — без настройки и обучения.',
                },
                {
                    title: 'Прозрачная загрузка',
                    text: 'Видно, сколько часов ушло на каждый проект и задачу, по дням и по людям.',
                },
                {
                    title: 'Отчёты в один клик',
                    text: 'Выгрузите отчёт для клиента или руководителя за любой период в CSV или PDF.',
                },
            ],
        },
        {
            type: BlockType.BannerBlock,
            title: 'Начните учитывать время уже сегодня',
            subtitle: '14 дней бесплатно, без привязки карты.',
            color: 'var(--g-color-base-generic)',
            button: {text: 'Попробовать бесплатно', url: SIGNUP_URL, theme: 'action'},
        },
    ],
};

export function App() {
    return (
        <PageConstructorProvider theme={Theme.Light} locale={{lang: 'ru'}}>
            <PageConstructor content={content} />
        </PageConstructorProvider>
    );
}
EOF
cat > src/App.css <<'EOF'
/* page-constructor's grid relies on a global border-box reset (see package docs) */
*,
*::before,
*::after {
    box-sizing: border-box;
}

body {
    margin: 0;
}
EOF
cat > vite.config.ts <<'EOF'
import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';
import dynamicImport from 'vite-plugin-dynamic-import';

export default defineConfig({
  plugins: [react(), dynamicImport()],
});
EOF
sed -i 's/<html lang="en">/<html lang="ru">/; s#<title>Gravity UI eval</title>#<title>Учёт времени для команд</title>#' index.html
npm run build 2>&1 | tail -25

ls node_modules/url 2>&1 | head -3; npm install url 2>&1 | tail -1
cat > vite.config.ts <<'EOF'
import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';
import dynamicImport from 'vite-plugin-dynamic-import';

export default defineConfig({
  plugins: [react(), dynamicImport()],
  resolve: {
    alias: [
      // page-constructor styles use webpack-style `~pkg/...` imports
      { find: /^~(.*)$/, replacement: '$1' },
      // page-constructor imports Node's `url` module; use the browser polyfill
      { find: /^url$/, replacement: 'url/' },
    ],
  },
});
EOF
npm run build 2>&1 | grep -v -i "deprecat\|╷\|│\|╵\|^ *$\|More info\|@import\|root stylesheet\|Recommendation\|mixins.scss\|automated migrator" | tail -20

mkdir -p .tmp-smoke && cat > .tmp-smoke/smoke.test.tsx <<'EOF'
import {renderToString} from 'react-dom/server';
import {ThemeProvider} from '@gravity-ui/uikit';
import {test, expect} from 'vitest';
import {App} from '../src/App';

test('renders', () => {
    const html = renderToString(<ThemeProvider theme="light"><App /></ThemeProvider>);
    for (const s of ['Знайте, куда уходит', 'Старт за минуту', 'Прозрачная загрузка', 'Отчёты в один клик', 'Попробовать бесплатно', 'href="/signup"']) {
        expect(html, s).toContain(s);
    }
    console.log((html.match(/<h[1-3][^>]*>/g) || []).length, 'headings');
});
EOF
npx vitest run --root . .tmp-smoke 2>&1 | grep -v -i deprecat | tail -15; rm -rf .tmp-smoke

